<div id="product-results">
<?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="surface table-scroll products-table-wrap"><table class="product-table" aria-label="Products"><thead><tr><th>Product / SKU</th><th>Category</th><th>Brand / Bikes</th><th class="number">Purchase</th><th class="number">Selling</th><th class="number">Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($listing['rows'] as $p): ?><tr><td data-label="Product"><a href="<?= e(url('/products/view')) ?>&amp;id=<?= (int)$p['id'] ?>"><strong><?= e($p['name']) ?></strong></a><small><?= e($p['sku']) ?></small><small><?= e($p['part_number']??'') ?></small></td><td data-label="Category / Subcategory"><?= e($p['category_name']) ?><small><?= e($p['subcategory_name']??'') ?></small></td><td data-label="Brand / Compatible bikes"><?= e($p['brand_name']??'—') ?><small class="bike-summary"><?= e($p['bikes']??'No bike mappings') ?></small></td><td class="number" data-label="Purchase price"><?= money($p['purchase_price']) ?></td><td class="number" data-label="Selling price"><?= money($p['selling_price']) ?></td><td class="number" data-label="Available stock"><?= $p['quantity']===null?'Not tracked':quantity($p['quantity']) ?><?php if($p['quantity']!==null && bccomp((string)$p['reorder_level'],'0',6)>0 && bccomp((string)$p['quantity'],(string)$p['reorder_level'],6)<=0): ?><small class="stock-warning">Low stock</small><?php endif; ?></td><td data-label="Status"><?= $p['archived_at']?'Archived':e(ucfirst($p['status'])) ?></td><td data-label="Actions"><div class="row-actions"><a href="<?= e(url('/products/view')) ?>&amp;id=<?= (int)$p['id'] ?>">View</a><?php if(!$p['archived_at']): ?><a href="<?= e(url('/products/form')) ?>&amp;id=<?= (int)$p['id'] ?>">Edit</a><?php endif; ?><a href="<?= e(url('/products/form')) ?>&amp;duplicate=<?= (int)$p['id'] ?>">Duplicate</a><?php if(!$p['archived_at']): ?><form method="post" action="<?= e(url('/products/archive')) ?>" data-product-confirm="Archive this product? Stock and historical movements will be retained."><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button>Archive</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table><?php if(!$listing['rows']): ?><div class="empty-state compact"><h3>No matching products</h3><p>Add a product or change the filters.</p></div><?php endif; ?></div>
<nav class="pagination" aria-label="Product pages"><span>Page <?= $listing['page'] ?> of <?= $listing['pages'] ?></span><?php foreach(['Previous'=>$listing['page']-1,'Next'=>$listing['page']+1] as $label=>$page): if($page<1 || $page>$listing['pages'])continue; ?><a class="button" href="index.php?<?= e(http_build_query(['route'=>'/products']+array_replace($filters,['page'=>$page]))) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>

</div>
